// Self-contained pure-JS QR Code SVG generator (supports byte mode up to version 6)
(function(global) {
  // GF(256) math for Reed-Solomon
  const EXP = new Uint8Array(512);
  const LOG = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];

  function polyMul(p1, p2) {
    const res = new Uint8Array(p1.length + p2.length - 1);
    for (let i = 0; i < p1.length; i++) {
      for (let j = 0; j < p2.length; j++) {
        if (p1[i] && p2[j]) {
          res[i + j] ^= EXP[LOG[p1[i]] + LOG[p2[j]]];
        }
      }
    }
    return res;
  }

  function rsGeneratorPoly(degree) {
    let g = new Uint8Array([1]);
    for (let i = 0; i < degree; i++) {
      g = polyMul(g, new Uint8Array([1, EXP[i]]));
    }
    return g;
  }

  function rsEncode(data, ecLen) {
    const gen = rsGeneratorPoly(ecLen);
    const msg = new Uint8Array(data.length + ecLen);
    msg.set(data, 0);
    for (let i = 0; i < data.length; i++) {
      const coef = msg[i];
      if (coef !== 0) {
        for (let j = 0; j < gen.length; j++) {
          msg[i + j] ^= EXP[LOG[gen[j]] + LOG[coef]];
        }
      }
    }
    return msg.slice(data.length);
  }

  // Version table for Error Correction Level L (Versions 1..6)
  // [totalDataCodewords, ecCodewordsPerBlock, numBlocks]
  const VERSION_TABLE = [
    null,
    [19, 7, 1],
    [34, 10, 1],
    [55, 15, 1],
    [80, 20, 1],
    [108, 26, 1],
    [136, 18, 2]
  ];

  const ALIGNMENT_POS = [
    null,
    [],
    [6, 18],
    [6, 22],
    [6, 26],
    [6, 30],
    [6, 34]
  ];

  function encodeQRMatrix(text) {
    const utf8 = new TextEncoder().encode(text);
    let ver = 1;
    while (ver <= 6 && VERSION_TABLE[ver][0] < utf8.length + 3) {
      ver++;
    }
    if (ver > 6) ver = 6;

    const [totalData, ecLen, numBlocks] = VERSION_TABLE[ver];
    const bits = [];
    function pushBits(val, len) {
      for (let i = len - 1; i >= 0; i--) bits.push((val >>> i) & 1);
    }

    // Byte mode indicator (0100)
    pushBits(0b0100, 4);
    pushBits(utf8.length, 8);
    for (let i = 0; i < utf8.length; i++) pushBits(utf8[i], 8);
    // Terminator
    for (let i = 0; i < 4 && bits.length < totalData * 8; i++) bits.push(0);
    while (bits.length % 8 !== 0) bits.push(0);

    const dataBytes = new Uint8Array(totalData);
    for (let i = 0; i < bits.length / 8 && i < totalData; i++) {
      let b = 0;
      for (let j = 0; j < 8; j++) b = (b << 1) | bits[i * 8 + j];
      dataBytes[i] = b;
    }
    const pads = [0xEC, 0x11];
    let padIdx = 0;
    for (let i = Math.floor(bits.length / 8); i < totalData; i++) {
      dataBytes[i] = pads[padIdx++ % 2];
    }

    // Split into blocks & compute EC
    const blockDataLen = Math.floor(totalData / numBlocks);
    const dataBlocks = [];
    const ecBlocks = [];
    for (let b = 0; b < numBlocks; b++) {
      const slice = dataBytes.slice(b * blockDataLen, (b + 1) * blockDataLen);
      dataBlocks.push(slice);
      ecBlocks.push(rsEncode(slice, ecLen));
    }

    const finalCodewords = [];
    for (let i = 0; i < blockDataLen; i++) {
      for (let b = 0; b < numBlocks; b++) finalCodewords.push(dataBlocks[b][i]);
    }
    for (let i = 0; i < ecLen; i++) {
      for (let b = 0; b < numBlocks; b++) finalCodewords.push(ecBlocks[b][i]);
    }

    const size = 17 + ver * 4;
    const matrix = Array.from({ length: size }, () => new Int8Array(size).fill(-1));
    const isFunc = Array.from({ length: size }, () => new Uint8Array(size));

    function setFuncModule(r, c, val) {
      matrix[r][c] = val ? 1 : 0;
      isFunc[r][c] = 1;
    }

    function drawFinder(r, c) {
      for (let dy = -1; dy <= 7; dy++) {
        for (let dx = -1; dx <= 7; dx++) {
          const y = r + dy, x = c + dx;
          if (y < 0 || y >= size || x < 0 || x >= size) continue;
          const inOuter = (dx >= 0 && dx <= 6 && (dy === 0 || dy === 6)) || (dy >= 0 && dy <= 6 && (dx === 0 || dx === 6));
          const inInner = dx >= 2 && dx <= 4 && dy >= 2 && dy <= 4;
          setFuncModule(y, x, inOuter || inInner ? 1 : 0);
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    // Timing patterns
    for (let i = 8; i < size - 8; i++) {
      setFuncModule(6, i, i % 2 === 0);
      setFuncModule(i, 6, i % 2 === 0);
    }

    // Alignment patterns
    const align = ALIGNMENT_POS[ver];
    for (let i = 0; i < align.length; i++) {
      for (let j = 0; j < align.length; j++) {
        if ((i === 0 && j === 0) || (i === 0 && j === align.length - 1) || (i === align.length - 1 && j === 0)) continue;
        const cy = align[i], cx = align[j];
        for (let dy = -2; dy <= 2; dy++) {
          for (let dx = -2; dx <= 2; dx++) {
            setFuncModule(cy + dy, cx + dx, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
          }
        }
      }
    }

    // Reserve format areas
    for (let i = 0; i < 9; i++) {
      if (i !== 6) {
        isFunc[8][i] = 1;
        isFunc[i][8] = 1;
      }
    }
    for (let i = 0; i < 8; i++) {
      isFunc[8][size - 1 - i] = 1;
      isFunc[size - 1 - i][8] = 1;
    }
    setFuncModule(size - 8, 8, 1);

    // Place data bits
    let bitIdx = 0;
    const totalBits = finalCodewords.length * 8;
    let upward = true;
    for (let right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (let vert = 0; vert < size; vert++) {
        const r = upward ? (size - 1 - vert) : vert;
        for (let j = 0; j < 2; j++) {
          const c = right - j;
          if (!isFunc[r][c]) {
            let bit = 0;
            if (bitIdx < totalBits) {
              bit = (finalCodewords[bitIdx >>> 3] >>> (7 - (bitIdx & 7))) & 1;
              bitIdx++;
            }
            // Apply mask 0: (r + c) % 2 === 0
            if ((r + c) % 2 === 0) bit ^= 1;
            matrix[r][c] = bit;
          }
        }
      }
      upward = !upward;
    }

    // Format info for Level L (01) and Mask 0 (000) -> precomputed BCH bits = 0x77c4
    const fmtBits = 0x77c4;
    for (let i = 0; i <= 5; i++) setFuncModule(8, i, (fmtBits >>> (14 - i)) & 1);
    setFuncModule(8, 7, (fmtBits >>> 8) & 1);
    setFuncModule(8, 8, (fmtBits >>> 7) & 1);
    setFuncModule(7, 8, (fmtBits >>> 6) & 1);
    for (let i = 9; i < 15; i++) setFuncModule(14 - i, 8, (fmtBits >>> (14 - i)) & 1);

    for (let i = 0; i < 8; i++) setFuncModule(8, size - 1 - i, (fmtBits >>> i) & 1);
    for (let i = 8; i < 15; i++) setFuncModule(size - 15 + i, 8, (fmtBits >>> i) & 1);

    return matrix;
  }

  global.renderQRCode = function(container, text, pxSize = 152) {
    const matrix = encodeQRMatrix(text);
    const n = matrix.length;
    let paths = '';
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) {
        if (matrix[r][c] === 1) {
          paths += `M${c},${r}h1v1h-1z`;
        }
      }
    }
    container.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${n} ${n}" width="${pxSize}" height="${pxSize}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#ffffff"/><path d="${paths}" fill="#0f172a"/></svg>`;
  };
})(window);
